function SalaryPlanDialog:Awake()
    self.oldLevel = checkNumber(CfUtils.GetLocalData(LOCAL_LEVEL_UP_KEY, "1"))
    self.playerNode = self.TxtPlayerName.transform.parent
    ---@type TableML.TableFile
    local tableFile = CfUtils.GetCfTable(AutoIds.IdSetting6511)
    self.configs = {}
    for i, row in pairs(tableFile) do
        local id = checkNumber(row:Get("id"))
        local name = parse_localizeText(row, "name")
        local point = checkNumber(row:Get("point"))
        local rewardNum = checkNumber(row:Get("rewardNum"))
        table.insert(self.configs, {
            id = id,
            name = name,
            point = point,
            num = rewardNum,
        })
    end
    SetButtonAction(self.ImgBlack.transform.parent:Find("BtnClose"), function()
        local rootTrans = self.ImgBlack.transform.parent:Find("Root")
        if rootTrans then
            ---@type UnityEngine.Animation
            local animation = rootTrans.gameObject:GetComponent(typeof(Animation))
            if animation then
                if animation:IsPlaying("SalaryPlanDialog_Entry") then
                    return
                end
            end
        end
        CfUtils.DialogBack()
    end)
    SetButtonAction(self.BtnTips.transform.parent:Find("BtnClose"), function()
        local rootTrans = self.ImgBlack.transform.parent:Find("Root")
        if rootTrans then
            ---@type UnityEngine.Animation
            local animation = rootTrans.gameObject:GetComponent(typeof(Animation))
            if animation then
                if animation:IsPlaying("SalaryPlanDialog_Entry") then
                    return
                end
            end
        end
        CfUtils.DialogBack()
    end)
    SetButtonAction(self.BtnTips, function()
        CfUtils.ShowModuleToast(self:GetParam(ParamDefine.TOAST_ID))
    end)
    SetButtonAction(self.playerNode:Find("BtnView"), function()
        if self.data then
            local id, config = self:GetCurrentJobLevel()
            CfUtils.DialogOpen(Constants.UITypeIds.SalaryPlanPopup, { delta = self:GetParam(ParamDefine.MONTHLY_DELTA), config = config })
        end
    end)
    SetButtonAction(self.BtnTips2, function()
        ---显示tips
        self.isShow = not self.isShow
        CfUtils.SetActive(self.BtnTips2.transform:Find("Tips"), self.isShow)
        --CfUtils.FillText(self.BtnTips2.transform:Find("Tips/Layout/Text"), localize("当前职级30天可领取的总数"))
    end)
    SetButtonAction(self.BtnGet.transform.parent:Find("BtnView"), function()
        if self.data then
            local id, config = self:GetCurrentJobLevel()
            CfUtils.DialogOpen(Constants.UITypeIds.SalaryPlanPopup, { delta = self:GetParam(ParamDefine.MONTHLY_DELTA), config = config })
        end
    end)
    SetButtonAction(self.BtnGet, function()
        ---领取奖励的逻辑
        if self.data then
            if not GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id27803) then
                GameUtils.Toast(GameUtils.GetUnlockDescrBySystemTogId(Constants.SystemToggleIds.Id27803))
                return
            end
            if checkNumber(self.data.hasDrawnTodayReward) == 0 then
                GameUtils.Request("Job/draw", {}, function(request, response)
                    if checkNumber(response.errCode) == 0 then
                        self.data.hasDrawnTodayReward = 1
                        GameUtils.SetRedPointNum(Constants.RedPointConst.MainVeteranAllowance, 0)
                        GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.MainVeteranAllowance)
                        local rewards = checkTable(response.data.rewards)
                        GoodsUtils.DrawRewards(rewards, true)
                        CfUtils.DialogOpen(Constants.UITypeIds.UICommonRewardPop, { rewards = rewards })
                        ---剧新界面
                        GameUtils.Request("Job/home", {}, function(xrequest, xresponse)
                            if checkNumber(xresponse.data.errCode) == 0 then
                                ---请求成功的情况下
                                self.data = xresponse.data
                                ---@type BackpackComponent
                                local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.BackpackComponent)
                                component.backpack[tostring(self:GetParam(ParamDefine.GOOD_ID))] = checkNumber(self.data.contributePointNum)
                                self:FreshUI()
                            end
                        end)
                    end
                end)
            end
        end
    end)
end

---GetCurrentJobLevel
---获取当前职级
function SalaryPlanDialog:GetCurrentJobLevel()
    local point = GoodsUtils.GetThingNo(self:GetParam(ParamDefine.GOOD_ID))
    local curLevel = 1
    local config = {}
    for i, v in pairs(self.configs) do
        if checkNumber(point) >= checkNumber(v.point) then
            curLevel = checkNumber(v.id)
            config = v
        end
    end
    return curLevel, config
end

---GetMaxJobLevel
---获取最大等级
function SalaryPlanDialog:GetMaxJobLevel()
    local maxLevel = 1
    local config = {}
    for i, v in pairs(self.configs) do
        maxLevel = checkNumber(v.id)
        config = v
    end
    return maxLevel, config
end

function SalaryPlanDialog:GetPreJobLevel(curLevel)
    local preLevel = 1
    local config = {}
    for i, v in pairs(self.configs) do
        if checkNumber(v.id) < curLevel then
            maxLevel = checkNumber(v.id)
            config = v
        end
    end
    return preLevel, config
end

---GetMaxJobLevel
function SalaryPlanDialog:GetNextJobLevel()
    local curLevel = self:GetCurrentJobLevel()
    local config = {}
    local maxLevel, maxConfig = self:GetMaxJobLevel()
    if curLevel == maxLevel then
        curLevel = maxLevel
        config = maxConfig
    else
        for i, v in pairs(self.configs) do
            if checkNumber(v.id) > curLevel then
                config = v
                break
            end
        end
    end
    return curLevel, config
end

function SalaryPlanDialog:GetParam(id)
    ---@type ParamsVo
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting6512, "Activity.ContractOfFood.Annihilation.ParamsVo", id)
    return checkNumber(vo.num)
end

---FreshNextLevelNumber
---剧新下一级的文本显示
function SalaryPlanDialog:FreshNextLevelNumber()
    local id, nextConfig = self:GetNextJobLevel()
    local maxId, _ = self:GetMaxJobLevel()
    local nextGoodTrans = self.BtnGet.transform.parent:Find("NextGoodGroup")
    if nextGoodTrans then
        if checkNumber(maxId) == checkNumber(id) then
            ---已经是最后一级了
            CfUtils.SetActive(nextGoodTrans:Find("ImgIcon"), false)
            CfUtils.FillText(nextGoodTrans:Find("TxtNumber"), "")
            CfUtils.FillText(nextGoodTrans:Find("TxtNumber/TxtNext"), localize("当前职级已满"))
        else
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self:GetParam(ParamDefine.REWARD_GOOD_ID))
            if goodsVo then
                CfUtils.FillImage(nextGoodTrans:Find("ImgIcon"), goodsVo.photoPath)
                CfUtils.FillText(nextGoodTrans:Find("TxtNumber"), checkNumber(nextConfig.num) * self:GetParam(ParamDefine.MONTHLY_DELTA))
            end
        end
    end
end

function SalaryPlanDialog:FreshUI(isFirst)
    isFirst = checkBool(isFirst)
    local id, config = self:GetCurrentJobLevel()
    local _, nextConfig = self:GetNextJobLevel()
    local point = GoodsUtils.GetThingNo(self:GetParam(ParamDefine.GOOD_ID))
    if id > self.oldLevel and isFirst then
        local _, preConfig = self:GetPreJobLevel(id)
        CfUtils.FillText(self.playerNode:Find("Mask/TxtLevelBefore"), preConfig.name)
        CfUtils.FillText(self.playerNode:Find("Mask/TxtLevelAfter"), config.name)
        CfUtils.FillText(self.TxtLevel, preConfig.name)
    else
        CfUtils.FillText(self.TxtLevel, config.name)
    end
    CfUtils.FillText(self.TxtNumStar, string.format("%d/%d", point, nextConfig.point))
    CfUtils.SetSliderPercent(self.Slider, point / checkNumber(nextConfig.point))

    self.flyStartNode = {}
    KTool.DestroyGameObjectChildren(self.Tasklist.gameObject, true)
    if #self.data.tasks > 0 then
        local goodsId = self:GetParam(ParamDefine.GOOD_ID)
        --Assets/BundleResources/Arts/Icons/Goods/goods_icon_5300026.png
        --local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        for i, v in pairs(self.data.tasks) do
            local go = KTool.Instantiate(self.Tasklist.gameObject, self.Cell.gameObject, true)
            KTool.SetActive(go, true)
            CfUtils.FillText(go.transform:Find("TxtTask"), tostring(v.taskTitle))
            if checkNumber(v.progress) >= checkNumber(v.targetNum) then
                table.insert(self.flyStartNode, go.transform:Find("TxtNumStar/ImgStar"))
            end
            CfUtils.SetUISwitchImage(go.transform:Find("Get"), checkNumber(v.progress) >= checkNumber(v.targetNum) and 1 or 2)
            CfUtils.FillImage(go.transform:Find("TxtNumStar/ImgStar"), string.format('Arts/Icons/Goods/goods_icon_%d.png', goodsId))
            if checkNumber(v.moduleId) == TaskType.WEEKLY then
                CfUtils.FillText(go.transform:Find("TxtNumStar"), tostring(v.point) .. '/' .. localize('周'))
            else
                CfUtils.FillText(go.transform:Find("TxtNumStar"), tostring(v.point) .. '/' .. localize('天'))
            end
        end
    end
    ---右铡
    CfUtils.FillText(self.TxtNum, checkNumber(config.num) * self:GetParam(ParamDefine.MONTHLY_DELTA))
    CfUtils.FillText(self.TxtNumStar2, self.data.totalRewardNum)
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self:GetParam(ParamDefine.REWARD_GOOD_ID))
    if goodsVo then
        CfUtils.FillImage(self.TxtNumStar2.transform.parent:Find("Imgicon"), goodsVo.photoPath)
        CfUtils.FillImage(self.TxtNumStar2.transform:Find("ImgIcon"), goodsVo.photoPath)
    end
    local env = CfUtils.GetLuaScr(self.GoodNode, "Game.Behaviours.GoodNodeMB")
    env:Reload(
            {
                goodsId = self:GetParam(ParamDefine.REWARD_GOOD_ID),
                text = "x" .. config.num,
                isShowNo = true
            }
    )
    env:SetClickButtonAction(function(goodsId)
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        if isTable(goodsVo) then
            GameUtils.ShowCommonTipsBoard(self.GoodNode.gameObject, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
        end
    end)
    CfUtils.SetActive(self.ImgIconLock, false)
    if not GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id27803) then
        CfUtils.SetActive(self.ImgIconLock, true)
        CfUtils.SetUISwitchText(self.ImgIconLock.transform:Find("text"), 2)
    elseif checkNumber(self.data.hasDrawnTodayReward) == 1 then
        CfUtils.SetActive(self.ImgIconLock, true)
        CfUtils.SetUISwitchText(self.ImgIconLock.transform:Find("text"), 1)
    end
    self:FreshNextLevelNumber()
end

function SalaryPlanDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local isSuccess = false
        CfUtils.SetActive(self.Tasklist.transform.parent, false)
        CfUtils.SetActive(self.BtnGet.transform.parent, false)
        GameUtils.Request("Job/home", {}, function(request, response)
            isSuccess = true
            CfUtils.SetActive(self.ImgBlack.transform.parent:Find("Root"), true)
            if checkNumber(response.data.errCode) == 0 then
                CfUtils.SetActive(self.Tasklist.transform.parent, true)
                CfUtils.SetActive(self.BtnGet.transform.parent, true)
                ---请求成功的情况下
                self.data = response.data
            end
        end)
        while not isSuccess do
            coroutine.yield()
        end
        if self.data and not isNull(self.data.contributePointNum) then
            ---@type BackpackComponent
            local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.BackpackComponent)
            component.backpack[tostring(self:GetParam(ParamDefine.GOOD_ID))] = checkNumber(self.data.contributePointNum)
        end
        self:FreshUI(true)
        --CfUtils.WriteLocalData("SALARY_FLY_EFFECT", "1")
        local showFly = CfUtils.GetLocalData("SALARY_FLY_EFFECT", "0")
        if checkInt(showFly) == 0 then
            ---每天的强行飞一次效果
            local days = CfUtils.GetLocalData("SALARY_FLY_EFFECT_TASK_EVERY_DAY", 0)
            if checkInt(days) < checkInt(os.date("%Y%m%d")) then
                CfUtils.WriteLocalData("SALARY_FLY_EFFECT_TASK_EVERY_DAY" , os.date("%Y%m%d"))
                showFly = 1
            end
        end
        if checkNumber(showFly) == 1 then
            CfUtils.WriteLocalData("SALARY_FLY_EFFECT", "0")
            CoYield(0.6)
            --需要飞特效
            if #self.data.tasks > 0 and #self.flyStartNode > 0 then
                local goodsId = self:GetParam(ParamDefine.GOOD_ID)
                --Assets/BundleResources/Arts/Icons/Goods/goods_icon_5300026.png
                --local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                for i, v in pairs(self.flyStartNode) do
                    ---存在完成的任务
                    if not isNull(v) then
                        self:FlyEffect(v.gameObject, self.TxtNumStar.transform:Find("ImgStar"), goodsId, true)
                    end
                end
                CoYield(0.3)
                self.flyStartNode = {}
            end
        end
        local id, config = self:GetCurrentJobLevel()
        if id > self.oldLevel then
            CoYield(0.5)
            ---存在升级的情况下
            CfUtils.PlayAnimation(self.playerNode, "SalaryPlanDialog_LevelChange")
            CoYield(0.45)
            CfUtils.FillText(self.TxtLevel, config.name)
            CoYield(0.65)
            CfUtils.WriteLocalData(LOCAL_LEVEL_UP_KEY, tostring(id))
        elseif id == self.oldLevel then
            CfUtils.WriteLocalData(LOCAL_LEVEL_UP_KEY, tostring(id))
        end
    end))
    return coWait
end

local DynamicLoadEffectPath = {
    Boom = "Effect/prefab/ui_prefab/UIFX_UICultivateEquipReclaimDialogBoom.prefab",
    BoomBoom2 = "Effect/prefab/ui_prefab/UIFX_UICultivateEquipReclaimDialogBoomBoom2.prefab",
    BoomMove = "Effect/prefab/ui_prefab/UIFX_UICultivateEquipReclaimDialogBoomMove.prefab",
}

--- 道具飞入顶部货币栏动画
---@param startGo UnityEngine.GameObject
---@param iconNode UnityEngine.GameObject
---@param goodsId integer
---@param isMore boolean | nil @ 是普通量的效果，还是大量的效果。default false
---@return UnityEngine.Coroutine
function SalaryPlanDialog:FlyEffect(startGo, iconNode, goodsId, isMore)
    local co = cs_coroutine.start(function()
        CS.Engine.UI.UIRaycastBlocker.Instance:AddCondition("StartGoodsFly")
        xTry(function()
            local parent = startGo.gameObject
            local boomLoader = ResourceModule.LoadBundleAsync(DynamicLoadEffectPath.Boom, nil, true)
            local boomMoveLoader = ResourceModule.LoadBundleAsync(DynamicLoadEffectPath.BoomMove, nil, true)
            local boomBoom2Loader = ResourceModule.LoadBundleAsync(DynamicLoadEffectPath.BoomBoom2, nil, true)
            local path = string.format('Arts/Icons/Goods/goods_icon_%d.png', goodsId)
            local TextureLoader = CS.Engine.Modules.TextureLoader
            local textureLoader = TextureLoader.Load(path, nil, CS.Engine.Modules.LoaderMode.Sync, true)
            local tex
            if textureLoader.IsSuccess then
                tex = textureLoader.Asset
            end
            textureLoader:Retain(startGo.gameObject)
            textureLoader:Release()
            while not boomLoader.IsCompleted or not boomMoveLoader.IsCompleted do
                coroutine.yield()
            end
            local boomGo = GameUtils.InstantiateGoByLoader(boomLoader, parent)
            local boomMoveGo = GameUtils.InstantiateGoByLoader(boomMoveLoader, parent)
            ---@type Game.Native.URP.URPCameraController
            local iconPosition = iconNode and iconNode.transform.position or parent -- 做一个容错，找不到顶部货币栏就原地播放
            --iconPosition = Vector3.New(iconPosition.x + 1.74, iconPosition.y + 1.56, 0)
            local name = isMore and "UIFX_MoreGoodsImgChange" or "UIFX_GoodsImgChange"
            local effectGo = boomMoveGo.transform:Find(name)
            local render
            if not isNull(effectGo) then
                render = effectGo:GetComponent(typeof(CS.UnityEngine.Renderer))
                if not isNull(render) then
                    local id = CS.UnityEngine.Shader.PropertyToID("_MainTex")
                    render.material:SetTexture(id, tex)
                end
            end

            local particleTargetMove = KTool.GetComponent(effectGo.gameObject, typeof(CS.Engine.UI.ParticleTargetMove))
            if not isNull(particleTargetMove) then
                particleTargetMove:Play(iconPosition)
            end
            CoYield(1.0)
            while not boomBoom2Loader.IsCompleted do
                coroutine.yield()
            end
            KTool.SafeDelete(boomGo)
            KTool.SafeDelete(boomMoveGo)

            local boomBoom2Go = GameUtils.InstantiateGoByLoader(boomBoom2Loader, parent)
            boomBoom2Go.transform.position = iconPosition
            CoYield(0.5)
            KTool.SafeDelete(boomBoom2Go)
            CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("StartGoodsFly")
        end, function()
            CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("StartGoodsFly")
        end)
    end)
    return co
end

